INSERT INTO "diagnostico"."banco_item_diagnostico"
  ("rango_edad", "habilidad", "nivel_dificultad", "forma", "enunciado", "contenido", "respuesta_correcta")
VALUES
  ('R1', 'LIT', 1, 'A', '¿De qué color es la pelota de Toby?', '{"orden":1,"lectura":{"clave":"R1-A-1","titulo":"Toby en el parque","texto":"Toby es un perro pequeño. Tiene manchas negras. Cada mañana corre al parque con Ana. Allí juega con una pelota roja. Cuando se cansa, toma agua y duerme bajo un árbol."},"opciones":["Azul","Negra","Roja"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R1', 'VOC', 1, 'A', 'Toby «se cansa». ¿Qué quiere decir?', '{"orden":2,"lectura":{"clave":"R1-A-1","titulo":"Toby en el parque","texto":"Toby es un perro pequeño. Tiene manchas negras. Cada mañana corre al parque con Ana. Allí juega con una pelota roja. Cuando se cansa, toma agua y duerme bajo un árbol."},"opciones":["Tiene mucha hambre","Ya no tiene fuerzas para jugar","Está muy contento"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R1', 'INF', 2, 'A', '¿Por qué Toby toma agua?', '{"orden":3,"lectura":{"clave":"R1-A-1","titulo":"Toby en el parque","texto":"Toby es un perro pequeño. Tiene manchas negras. Cada mañana corre al parque con Ana. Allí juega con una pelota roja. Cuando se cansa, toma agua y duerme bajo un árbol."},"opciones":["Porque corrió y jugó mucho","Porque la pelota es roja","Porque Ana se fue"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R1', 'CRI', 2, 'A', '¿Te parece bien que Ana lleve a Toby al parque?', '{"orden":4,"lectura":{"clave":"R1-A-1","titulo":"Toby en el parque","texto":"Toby es un perro pequeño. Tiene manchas negras. Cada mañana corre al parque con Ana. Allí juega con una pelota roja. Cuando se cansa, toma agua y duerme bajo un árbol."},"opciones":["Sí, porque así Toby juega y se mueve","No, porque los perros no juegan","Sí, porque el árbol es grande"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R1', 'ARG', 3, 'A', 'Ana dice: «Toby es mi compañero». ¿Qué parte del texto lo muestra mejor?', '{"orden":5,"lectura":{"clave":"R1-A-1","titulo":"Toby en el parque","texto":"Toby es un perro pequeño. Tiene manchas negras. Cada mañana corre al parque con Ana. Allí juega con una pelota roja. Cuando se cansa, toma agua y duerme bajo un árbol."},"opciones":["Tiene manchas negras","Duerme bajo un árbol","Cada mañana corre al parque con Ana"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R1', 'LIT', 2, 'A', '¿Qué hay en el huerto de la escuela?', '{"orden":6,"lectura":{"clave":"R1-A-2","titulo":"La lluvia en el huerto","texto":"En el huerto de la escuela hay tomates y lechugas. Hoy llovió toda la mañana. Por eso los niños no regaron las plantas. En la tarde salió el sol y las hojas brillaban."},"opciones":["Flores y árboles","Papas y maíz","Tomates y lechugas"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R1', 'VOC', 2, 'A', 'Las hojas «brillaban». ¿Qué significa?', '{"orden":7,"lectura":{"clave":"R1-A-2","titulo":"La lluvia en el huerto","texto":"En el huerto de la escuela hay tomates y lechugas. Hoy llovió toda la mañana. Por eso los niños no regaron las plantas. En la tarde salió el sol y las hojas brillaban."},"opciones":["Estaban rotas","Se veían con luz","Estaban secas"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R1', 'INF', 3, 'A', '¿Por qué los niños no regaron las plantas?', '{"orden":8,"lectura":{"clave":"R1-A-2","titulo":"La lluvia en el huerto","texto":"En el huerto de la escuela hay tomates y lechugas. Hoy llovió toda la mañana. Por eso los niños no regaron las plantas. En la tarde salió el sol y las hojas brillaban."},"opciones":["Porque la lluvia ya les dio agua","Porque no les gustan las plantas","Porque era de noche"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R1', 'CRI', 3, 'A', '¿Para qué sirve tener un huerto en la escuela?', '{"orden":9,"lectura":{"clave":"R1-A-2","titulo":"La lluvia en el huerto","texto":"En el huerto de la escuela hay tomates y lechugas. Hoy llovió toda la mañana. Por eso los niños no regaron las plantas. En la tarde salió el sol y las hojas brillaban."},"opciones":["Para que llueva más","Para aprender a cuidar plantas","Para no ir a clases"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R1', 'ARG', 3, 'A', 'Luis cree que la lluvia ayudó al huerto. ¿Qué razón le da la razón?', '{"orden":10,"lectura":{"clave":"R1-A-2","titulo":"La lluvia en el huerto","texto":"En el huerto de la escuela hay tomates y lechugas. Hoy llovió toda la mañana. Por eso los niños no regaron las plantas. En la tarde salió el sol y las hojas brillaban."},"opciones":["En la tarde salió el sol","Las plantas tuvieron agua sin regarlas","En el huerto hay tomates"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R2', 'LIT', 1, 'A', '¿Qué comía Killa cada mañana?', '{"orden":1,"lectura":{"clave":"R2-A-1","titulo":"Killa y el cóndor","texto":"En lo alto de los Andes vivía una vicuña llamada Killa. Todas las mañanas comía ichu junto al lago. Un día vio la sombra enorme de un cóndor que volaba en círculos. Killa se quedó quieta entre las rocas hasta que el ave se alejó. Desde entonces, siempre mira al cielo antes de bajar al lago."},"opciones":["Maíz","Peces","Flores","Ichu"]}'::jsonb, '{"indice":3}'::jsonb),
  ('R2', 'VOC', 2, 'A', 'El cóndor volaba «en círculos». ¿Cómo se movía?', '{"orden":2,"lectura":{"clave":"R2-A-1","titulo":"Killa y el cóndor","texto":"En lo alto de los Andes vivía una vicuña llamada Killa. Todas las mañanas comía ichu junto al lago. Un día vio la sombra enorme de un cóndor que volaba en círculos. Killa se quedó quieta entre las rocas hasta que el ave se alejó. Desde entonces, siempre mira al cielo antes de bajar al lago."},"opciones":["Volaba en línea recta","Caminaba por el suelo","Daba vueltas en el aire","Bajaba al lago"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R2', 'INF', 2, 'A', '¿Por qué Killa se quedó quieta entre las rocas?', '{"orden":3,"lectura":{"clave":"R2-A-1","titulo":"Killa y el cóndor","texto":"En lo alto de los Andes vivía una vicuña llamada Killa. Todas las mañanas comía ichu junto al lago. Un día vio la sombra enorme de un cóndor que volaba en círculos. Killa se quedó quieta entre las rocas hasta que el ave se alejó. Desde entonces, siempre mira al cielo antes de bajar al lago."},"opciones":["Para que el cóndor no la viera","Porque estaba dormida","Porque quería jugar","Porque tenía frío"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R2', 'CRI', 2, 'A', '¿Qué aprendió Killa después de ese día?', '{"orden":4,"lectura":{"clave":"R2-A-1","titulo":"Killa y el cóndor","texto":"En lo alto de los Andes vivía una vicuña llamada Killa. Todas las mañanas comía ichu junto al lago. Un día vio la sombra enorme de un cóndor que volaba en círculos. Killa se quedó quieta entre las rocas hasta que el ave se alejó. Desde entonces, siempre mira al cielo antes de bajar al lago."},"opciones":["A tener cuidado antes de bajar al lago","A volar como el cóndor","A comer menos ichu","A nadar en el lago"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R2', 'ARG', 3, 'A', 'Rosa dice que Killa es prudente. ¿Qué oración lo demuestra mejor?', '{"orden":5,"lectura":{"clave":"R2-A-1","titulo":"Killa y el cóndor","texto":"En lo alto de los Andes vivía una vicuña llamada Killa. Todas las mañanas comía ichu junto al lago. Un día vio la sombra enorme de un cóndor que volaba en círculos. Killa se quedó quieta entre las rocas hasta que el ave se alejó. Desde entonces, siempre mira al cielo antes de bajar al lago."},"opciones":["Comía ichu junto al lago","Siempre mira al cielo antes de bajar al lago","Vivía en lo alto de los Andes","Vio la sombra de un cóndor"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R2', 'LIT', 2, 'A', '¿Qué mezclaron Mateo y Lucía?', '{"orden":6,"lectura":{"clave":"R2-A-2","titulo":"El volcán de la feria","texto":"Mateo y Lucía prepararon un volcán para la feria de ciencias. Mezclaron bicarbonato con vinagre y una espuma roja salió por la boca del volcán. Los visitantes aplaudieron. La profesora les preguntó por qué salía espuma, y Lucía explicó que los dos ingredientes, al juntarse, producen un gas."},"opciones":["Agua con sal","Arena con piedras","Bicarbonato con vinagre","Leche con azúcar"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R2', 'VOC', 3, 'A', 'Los visitantes «aplaudieron». ¿Qué hicieron?', '{"orden":7,"lectura":{"clave":"R2-A-2","titulo":"El volcán de la feria","texto":"Mateo y Lucía prepararon un volcán para la feria de ciencias. Mezclaron bicarbonato con vinagre y una espuma roja salió por la boca del volcán. Los visitantes aplaudieron. La profesora les preguntó por qué salía espuma, y Lucía explicó que los dos ingredientes, al juntarse, producen un gas."},"opciones":["Golpearon sus palmas para felicitarlos","Se fueron de la feria","Hicieron preguntas","Se asustaron"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R2', 'INF', 3, 'A', '¿Cómo se sintieron los visitantes al ver el volcán?', '{"orden":8,"lectura":{"clave":"R2-A-2","titulo":"El volcán de la feria","texto":"Mateo y Lucía prepararon un volcán para la feria de ciencias. Mezclaron bicarbonato con vinagre y una espuma roja salió por la boca del volcán. Los visitantes aplaudieron. La profesora les preguntó por qué salía espuma, y Lucía explicó que los dos ingredientes, al juntarse, producen un gas."},"opciones":["Se aburrieron","Les gustó mucho","Se enojaron","Tuvieron miedo"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R2', 'CRI', 3, 'A', '¿Por qué es importante la explicación de Lucía?', '{"orden":9,"lectura":{"clave":"R2-A-2","titulo":"El volcán de la feria","texto":"Mateo y Lucía prepararon un volcán para la feria de ciencias. Mezclaron bicarbonato con vinagre y una espuma roja salió por la boca del volcán. Los visitantes aplaudieron. La profesora les preguntó por qué salía espuma, y Lucía explicó que los dos ingredientes, al juntarse, producen un gas."},"opciones":["Porque el volcán era rojo","Porque la feria terminó","Porque Mateo no habló","Porque muestra que entendió lo que pasó"]}'::jsonb, '{"indice":3}'::jsonb),
  ('R2', 'ARG', 3, 'A', 'Mateo dice: «Nuestro volcán fue un experimento de verdad». ¿Qué dato lo apoya?', '{"orden":10,"lectura":{"clave":"R2-A-2","titulo":"El volcán de la feria","texto":"Mateo y Lucía prepararon un volcán para la feria de ciencias. Mezclaron bicarbonato con vinagre y una espuma roja salió por la boca del volcán. Los visitantes aplaudieron. La profesora les preguntó por qué salía espuma, y Lucía explicó que los dos ingredientes, al juntarse, producen un gas."},"opciones":["La espuma era roja","Lucía explicó por qué se produce el gas","Había muchos visitantes","La feria era en la escuela"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R2', 'LIT', 3, 'A', '¿Qué llevan las abejas al volar de flor en flor?', '{"orden":11,"lectura":{"clave":"R2-A-3","titulo":"Las abejas del valle","texto":"En el valle de Urubamba, don Pedro cuida colmenas de abejas. Él sabe que las abejas no solo producen miel: al volar de flor en flor llevan polen y ayudan a que nazcan frutos. Por eso, cuando un vecino quiso fumigar su campo con veneno, don Pedro le pidió que buscara otra manera de cuidar sus cultivos."},"opciones":["Agua","Semillas","Polen","Hojas"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R2', 'VOC', 3, 'A', '«Fumigar» un campo es…', '{"orden":12,"lectura":{"clave":"R2-A-3","titulo":"Las abejas del valle","texto":"En el valle de Urubamba, don Pedro cuida colmenas de abejas. Él sabe que las abejas no solo producen miel: al volar de flor en flor llevan polen y ayudan a que nazcan frutos. Por eso, cuando un vecino quiso fumigar su campo con veneno, don Pedro le pidió que buscara otra manera de cuidar sus cultivos."},"opciones":["Sembrar árboles","Echarle productos para matar insectos","Regarlo con agua","Cosechar sus frutos"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R2', 'INF', 4, 'A', '¿Por qué don Pedro no quería que fumigaran con veneno?', '{"orden":13,"lectura":{"clave":"R2-A-3","titulo":"Las abejas del valle","texto":"En el valle de Urubamba, don Pedro cuida colmenas de abejas. Él sabe que las abejas no solo producen miel: al volar de flor en flor llevan polen y ayudan a que nazcan frutos. Por eso, cuando un vecino quiso fumigar su campo con veneno, don Pedro le pidió que buscara otra manera de cuidar sus cultivos."},"opciones":["Porque no le gusta la miel","Porque el campo era suyo","Porque quería vender veneno","Porque podía dañar a sus abejas"]}'::jsonb, '{"indice":3}'::jsonb),
  ('R2', 'CRI', 4, 'A', '¿Qué opinas del pedido de don Pedro?', '{"orden":14,"lectura":{"clave":"R2-A-3","titulo":"Las abejas del valle","texto":"En el valle de Urubamba, don Pedro cuida colmenas de abejas. Él sabe que las abejas no solo producen miel: al volar de flor en flor llevan polen y ayudan a que nazcan frutos. Por eso, cuando un vecino quiso fumigar su campo con veneno, don Pedro le pidió que buscara otra manera de cuidar sus cultivos."},"opciones":["Es malo: las abejas no sirven","Da igual: la miel se compra","Es razonable: cuidar a las abejas ayuda a los cultivos","Es injusto: el vecino no tiene campo"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R2', 'ARG', 4, 'A', '¿Qué razón usaría don Pedro para convencer al vecino?', '{"orden":15,"lectura":{"clave":"R2-A-3","titulo":"Las abejas del valle","texto":"En el valle de Urubamba, don Pedro cuida colmenas de abejas. Él sabe que las abejas no solo producen miel: al volar de flor en flor llevan polen y ayudan a que nazcan frutos. Por eso, cuando un vecino quiso fumigar su campo con veneno, don Pedro le pidió que buscara otra manera de cuidar sus cultivos."},"opciones":["La miel es dulce","Las abejas vuelan rápido","Sin abejas habría menos frutos en el valle","Él tiene muchas colmenas"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R3', 'LIT', 2, 'A', '¿Qué hicieron con el plástico reunido?', '{"orden":1,"lectura":{"clave":"R3-A-1","titulo":"La campaña del plástico","texto":"Los estudiantes de sexto grado notaron que en el recreo los tachos se llenaban de botellas de plástico. Decidieron organizar una campaña: colocaron tachos de colores, hicieron afiches y pesaron cada semana lo que juntaban. En un mes reunieron 40 kilos de plástico, que vendieron a una recicladora para comprar libros."},"opciones":["Lo botaron al mar","Lo guardaron en el aula","Lo regalaron a otra escuela","Lo vendieron para comprar libros"]}'::jsonb, '{"indice":3}'::jsonb),
  ('R3', 'VOC', 2, 'A', 'Una «campaña» es…', '{"orden":2,"lectura":{"clave":"R3-A-1","titulo":"La campaña del plástico","texto":"Los estudiantes de sexto grado notaron que en el recreo los tachos se llenaban de botellas de plástico. Decidieron organizar una campaña: colocaron tachos de colores, hicieron afiches y pesaron cada semana lo que juntaban. En un mes reunieron 40 kilos de plástico, que vendieron a una recicladora para comprar libros."},"opciones":["Un tipo de tacho","Una clase de matemática","Un viaje al campo","Un conjunto de acciones organizadas para lograr algo"]}'::jsonb, '{"indice":3}'::jsonb),
  ('R3', 'INF', 3, 'A', '¿Para qué pesaban cada semana lo que juntaban?', '{"orden":3,"lectura":{"clave":"R3-A-1","titulo":"La campaña del plástico","texto":"Los estudiantes de sexto grado notaron que en el recreo los tachos se llenaban de botellas de plástico. Decidieron organizar una campaña: colocaron tachos de colores, hicieron afiches y pesaron cada semana lo que juntaban. En un mes reunieron 40 kilos de plástico, que vendieron a una recicladora para comprar libros."},"opciones":["Para saber cuánto avanzaban","Para hacer ejercicio","Para vender los tachos","Para cansarse menos"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R3', 'CRI', 3, 'A', '¿Qué parte de la campaña ayudó más a que otros participaran?', '{"orden":4,"lectura":{"clave":"R3-A-1","titulo":"La campaña del plástico","texto":"Los estudiantes de sexto grado notaron que en el recreo los tachos se llenaban de botellas de plástico. Decidieron organizar una campaña: colocaron tachos de colores, hicieron afiches y pesaron cada semana lo que juntaban. En un mes reunieron 40 kilos de plástico, que vendieron a una recicladora para comprar libros."},"opciones":["Pesar el plástico","Los afiches y los tachos de colores","Venderlo a la recicladora","Que fueran de sexto grado"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R3', 'ARG', 3, 'A', 'Un profesor dice que la campaña fue un éxito. ¿Qué dato lo demuestra mejor?', '{"orden":5,"lectura":{"clave":"R3-A-1","titulo":"La campaña del plástico","texto":"Los estudiantes de sexto grado notaron que en el recreo los tachos se llenaban de botellas de plástico. Decidieron organizar una campaña: colocaron tachos de colores, hicieron afiches y pesaron cada semana lo que juntaban. En un mes reunieron 40 kilos de plástico, que vendieron a una recicladora para comprar libros."},"opciones":["Los tachos eran de colores","Reunieron 40 kilos en un mes","Era la hora del recreo","Eran de sexto grado"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R3', 'LIT', 3, 'A', '¿Dónde está el nevado Pastoruri?', '{"orden":6,"lectura":{"clave":"R3-A-2","titulo":"El agua del nevado","texto":"El nevado Pastoruri, en Áncash, ha perdido gran parte de su hielo en los últimos treinta años. Los científicos explican que el aumento de la temperatura del planeta derrite los glaciares más rápido de lo que se forman. Muchas comunidades de la sierra y de la costa dependen del agua que baja de estos nevados para beber y regar sus cultivos."},"opciones":["En Cusco","En Áncash","En Loreto","En Tacna"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R3', 'VOC', 3, 'A', 'Un «glaciar» es…', '{"orden":7,"lectura":{"clave":"R3-A-2","titulo":"El agua del nevado","texto":"El nevado Pastoruri, en Áncash, ha perdido gran parte de su hielo en los últimos treinta años. Los científicos explican que el aumento de la temperatura del planeta derrite los glaciares más rápido de lo que se forman. Muchas comunidades de la sierra y de la costa dependen del agua que baja de estos nevados para beber y regar sus cultivos."},"opciones":["Un río de la costa","Una gran masa de hielo en las montañas","Un tipo de cultivo","Una ciudad de la sierra"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R3', 'INF', 4, 'A', '¿Qué podría pasar si el nevado sigue perdiendo hielo?', '{"orden":8,"lectura":{"clave":"R3-A-2","titulo":"El agua del nevado","texto":"El nevado Pastoruri, en Áncash, ha perdido gran parte de su hielo en los últimos treinta años. Los científicos explican que el aumento de la temperatura del planeta derrite los glaciares más rápido de lo que se forman. Muchas comunidades de la sierra y de la costa dependen del agua que baja de estos nevados para beber y regar sus cultivos."},"opciones":["Habría más nieve en la costa","Los cultivos crecerían más","Habría menos agua para las comunidades","Bajaría la temperatura"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R3', 'CRI', 4, 'A', '¿Para qué menciona el texto a las comunidades de la costa?', '{"orden":9,"lectura":{"clave":"R3-A-2","titulo":"El agua del nevado","texto":"El nevado Pastoruri, en Áncash, ha perdido gran parte de su hielo en los últimos treinta años. Los científicos explican que el aumento de la temperatura del planeta derrite los glaciares más rápido de lo que se forman. Muchas comunidades de la sierra y de la costa dependen del agua que baja de estos nevados para beber y regar sus cultivos."},"opciones":["Para hablar de la playa","Para mostrar que el problema afecta a más personas","Para cambiar de tema","Porque allí hay nevados"]}'::jsonb, '{"indice":1}'::jsonb),
  ('R3', 'ARG', 4, 'A', '¿Qué argumento usarías para pedir que se cuiden los glaciares?', '{"orden":10,"lectura":{"clave":"R3-A-2","titulo":"El agua del nevado","texto":"El nevado Pastoruri, en Áncash, ha perdido gran parte de su hielo en los últimos treinta años. Los científicos explican que el aumento de la temperatura del planeta derrite los glaciares más rápido de lo que se forman. Muchas comunidades de la sierra y de la costa dependen del agua que baja de estos nevados para beber y regar sus cultivos."},"opciones":["Muchas personas dependen de su agua","El hielo es blanco","Los científicos estudian mucho","El nevado es alto"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R3', 'LIT', 4, 'A', '¿Qué propuso Valeria?', '{"orden":11,"lectura":{"clave":"R3-A-3","titulo":"¿Ropa libre los viernes?","texto":"En una asamblea escolar, Valeria propuso que los estudiantes pudieran ir con ropa libre los viernes. Dijo que así cada uno expresaría su estilo y estaría más cómodo. Diego no estuvo de acuerdo: afirmó que el uniforme evita que algunos se sientan menos por no tener ropa de marca. La directora pidió que ambos grupos presentaran una encuesta antes de decidir."},"opciones":["Eliminar el uniforme para siempre","Comprar ropa de marca","Ir con ropa libre los viernes","Hacer asambleas todos los días"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R3', 'VOC', 4, 'A', 'Expresar su «estilo» quiere decir mostrar…', '{"orden":12,"lectura":{"clave":"R3-A-3","titulo":"¿Ropa libre los viernes?","texto":"En una asamblea escolar, Valeria propuso que los estudiantes pudieran ir con ropa libre los viernes. Dijo que así cada uno expresaría su estilo y estaría más cómodo. Diego no estuvo de acuerdo: afirmó que el uniforme evita que algunos se sientan menos por no tener ropa de marca. La directora pidió que ambos grupos presentaran una encuesta antes de decidir."},"opciones":["Su manera propia de vestirse y de ser","Su nota en el colegio","Su edad","Su lugar en la fila"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R3', 'INF', 5, 'A', '¿Por qué la directora pidió una encuesta?', '{"orden":13,"lectura":{"clave":"R3-A-3","titulo":"¿Ropa libre los viernes?","texto":"En una asamblea escolar, Valeria propuso que los estudiantes pudieran ir con ropa libre los viernes. Dijo que así cada uno expresaría su estilo y estaría más cómodo. Diego no estuvo de acuerdo: afirmó que el uniforme evita que algunos se sientan menos por no tener ropa de marca. La directora pidió que ambos grupos presentaran una encuesta antes de decidir."},"opciones":["Porque no le interesaba el tema","Para castigar a Diego","Para conocer la opinión de todos antes de decidir","Para vender uniformes"]}'::jsonb, '{"indice":2}'::jsonb),
  ('R3', 'CRI', 5, 'A', '¿Qué argumento piensa más en los compañeros que tienen menos?', '{"orden":14,"lectura":{"clave":"R3-A-3","titulo":"¿Ropa libre los viernes?","texto":"En una asamblea escolar, Valeria propuso que los estudiantes pudieran ir con ropa libre los viernes. Dijo que así cada uno expresaría su estilo y estaría más cómodo. Diego no estuvo de acuerdo: afirmó que el uniforme evita que algunos se sientan menos por no tener ropa de marca. La directora pidió que ambos grupos presentaran una encuesta antes de decidir."},"opciones":["El de Diego, porque cuida que nadie se sienta menos","El de Valeria, porque habla de comodidad","Ninguno, porque solo hablan de ropa","El de la directora, porque es mayor"]}'::jsonb, '{"indice":0}'::jsonb),
  ('R3', 'ARG', 5, 'A', 'Si quisieras apoyar a Valeria sin olvidar la idea de Diego, ¿qué propondrías?', '{"orden":15,"lectura":{"clave":"R3-A-3","titulo":"¿Ropa libre los viernes?","texto":"En una asamblea escolar, Valeria propuso que los estudiantes pudieran ir con ropa libre los viernes. Dijo que así cada uno expresaría su estilo y estaría más cómodo. Diego no estuvo de acuerdo: afirmó que el uniforme evita que algunos se sientan menos por no tener ropa de marca. La directora pidió que ambos grupos presentaran una encuesta antes de decidir."},"opciones":["Que solo vengan con ropa de marca","Que nadie use uniforme nunca","Que no se haga la encuesta","Ropa libre los viernes con una regla sencilla para todos"]}'::jsonb, '{"indice":3}'::jsonb),
