  ('R2', 'LIT', 3, 'B', '¿Qué árboles registran los jóvenes?', '{"orden":11,"lectura":{"clave":"R2-B-3","titulo":"Los guardianes del bosque","texto":"En Madre de Dios, un grupo de jóvenes recorre el bosque para registrar los árboles de castaña. Anotan en una libreta dónde está cada árbol y cuántos frutos da. Con esa información, las familias planifican la cosecha sin cortar árboles. Además, avisan a las autoridades si ven a madereros ilegales."},"opciones":["Palmeras","Pinos","Eucaliptos","Árboles de castaña"]}'::jsonb, '{"indice":3}'::jsonb),
  ('R2', 'VOC', 3, 'B', '«Planificar» la cosecha es…', '{"orden":12,"lectura":{"clave":"R2-B-3","titulo":"Los guardianes del bosque","texto":"En Madre de Dios, un grupo de jóvenes recorre el bosque para registrar los árboles de castaña. Anotan en una libreta dónde está cada árbol y cuántos frutos da. Con esa información, las familias planifican la cosecha sin cortar árboles. Además, avisan a las autoridades si ven a madereros ilegales."},"opciones":["Organizarla antes de hacerla","Hacerla sin pensar","Cancelarla","Venderla"]}'::jsonb, '{"indice":0}'::jsonb),
